function normalizeProgress(value: unknown): Progress | null {
  if (!value || typeof value !== 'object') return null
  const data = value as Partial<Progress>
  if (!Array.isArray(data.completedLessons)) return null
  const safeCount = (value: unknown, max = 100000) => typeof value === 'number' && Number.isFinite(value) ? Math.min(max, Math.max(0, Math.floor(value))) : 0
  const attemptedAnswers = safeCount(data.attemptedAnswers)
  const correctAnswers = Math.min(attemptedAnswers, safeCount(data.correctAnswers))
  const quizHistory = Array.isArray(data.quizHistory) ? data.quizHistory.filter((item): item is QuizRecord => {
    if (!item || typeof item !== 'object') return false
    const record = item as QuizRecord
    return typeof record.category === 'string' && record.category.length < 50 &&
      typeof record.difficulty === 'string' && record.difficulty.length < 30 &&
      typeof record.completedAt === 'string' && record.completedAt.length < 60 &&
      Number.isInteger(record.total) && record.total > 0 && record.total <= 30 &&
      Number.isInteger(record.score) && record.score >= 0 && record.score <= record.total
  }).slice(-100) : []
  return {
    completedLessons: [...new Set(data.completedLessons.filter((id): id is string => typeof id === 'string' && lessons.some(l => l.id === id)))],
    attemptedAnswers, correctAnswers, phishingIndex: safeCount(data.phishingIndex),
    quizBest: Math.min(5, safeCount(data.quizBest)),
    quizHistory
  }
}
const completedQuizAttempts = (history: QuizRecord[]) => history.filter(r => r.kind === 'attempt' || (r.kind !== 'topic' && (r.category === 'All topics' || r.total > 1)))
function loadProgress(): Progress { try { const value = JSON.parse(localStorage.getItem('cybershield-progress-v1') || 'null'); return normalizeProgress(value) ?? initial } catch { return initial } }
function downloadReport(progress: Progress) {
  const history = progress.quizHistory || []
  const report = {
    project: 'CyberShield — Learn. Detect. Defend.',
    generatedAt: new Date().toISOString(),
    progressBackup: progress,
    completedLessons: progress.completedLessons,
    lessonsAvailable: lessons.length,
    phishingAttempts: progress.attemptedAnswers,
    correctPhishingAnswers: progress.correctAnswers,
    bestQuizScore: progress.quizBest,
    quizAttempts: completedQuizAttempts(history).length,
    recentQuizAttempts: completedQuizAttempts(history).slice(-15),
    topicPerformance: ['Phishing','Authentication','Privacy','Network safety'].map(topic => { const records = history.filter(r => r.category === topic && r.kind !== 'attempt' || r.category === topic && r.kind === 'attempt' && r.total > 1); return {topic, attempts: records.length, correct: records.reduce((sum,r) => sum + r.score,0), questions: records.reduce((sum,r) => sum + r.total,0)} }),
    quizQuestionsAvailable: quizQuestions.length,
    accuracyPercent: progress.attemptedAnswers ? Math.round(progress.correctAnswers / progress.attemptedAnswers * 100) : 0,
    note: 'Self-directed educational practice; not a professional certification or security assessment.',
  }
  const blob = new Blob([JSON.stringify(report, null, 2)], { type: 'application/json' })
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = 'cybershield-learning-report.json'
  link.click()
  URL.revokeObjectURL(url)
}
function downloadPrintableReport(progress: Progress) {
  const history = progress.quizHistory || []
  const escapeHtml = (value: string) => value.replace(/[&<>"']/g, character => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character] || character))
  const rows = ['Phishing','Authentication','Privacy','Network safety'].map(topic => {
    const records = history.filter(r => r.category === topic)
    const correct = records.reduce((sum,r) => sum + r.score,0)
    const total = records.reduce((sum,r) => sum + r.total,0)
    return '<tr><td>' + escapeHtml(topic) + '</td><td>' + (total ? Math.round(correct / total * 100) + '%' : 'Not yet assessed') + '</td><td>' + records.length + '</td></tr>'
  }).join('')
  const accuracy = progress.attemptedAnswers ? Math.round(progress.correctAnswers / progress.attemptedAnswers * 100) + '%' : 'Not yet assessed'
  const html = `<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CyberShield Learning Report</title><style>body{font-family:Arial,Helvetica,sans-serif;color:#263d3a;max-width:780px;margin:48px auto;padding:0 25px;line-height:1.6}header{border-bottom:3px solid #176b69;padding-bottom:24px}h1{font-size:30px;letter-spacing:-1px;margin:6px 0}h2{font-size:18px;margin-top:32px}.kicker{color:#176b69;font-size:12px;font-weight:bold;letter-spacing:2px}.muted{color:#6b7e7a}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:25px 0}.metric{background:#eff5f1;padding:16px;border-radius:8px}.metric strong{display:block;font-size:25px}.metric span{font-size:11px}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #dce7e0;text-align:left;padding:12px}th{background:#f1f6f2}footer{margin-top:40px;font-size:11px;color:#72837d;border-top:1px solid #dce7e0;padding-top:16px}@media print{body{margin:12px auto}.metric{print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style></head><body><header><div class="kicker">CYBERSHIELD · LEARNING SUMMARY</div><h1>Personal learning report</h1><p class="muted">Generated ${escapeHtml(new Date().toLocaleDateString())} · Progress saved locally on this device</p></header><div class="metrics"><div class="metric"><strong>${progress.completedLessons.length}/${lessons.length}</strong><span>Modules completed</span></div><div class="metric"><strong>${accuracy}</strong><span>Phishing practice accuracy</span></div><div class="metric"><strong>${completedQuizAttempts(history).length}</strong><span>Recorded quiz attempts</span></div></div><h2>Completed learning modules</h2><p>${progress.completedLessons.length ? lessons.filter(l => progress.completedLessons.includes(l.id)).map(l => escapeHtml(l.title)).join(' · ') : 'No modules completed yet.'}</p><h2>Quiz topic performance</h2><table><thead><tr><th>Topic</th><th>Accuracy</th><th>Attempts</th></tr></thead><tbody>${rows}</tbody></table><h2>Practice overview</h2><p>Phishing messages reviewed: ${progress.attemptedAnswers}. Correct assessments: ${progress.correctAnswers}. Best beginner all-topic quiz: ${progress.quizBest}/5.</p><footer>This document summarises self-directed educational activity. It is not a certification, identity verification, or professional security assessment. To save a PDF, open this file in a browser and choose Print → Save as PDF.</footer></body></html>`
  const blob = new Blob([html], {type:'text/html;charset=utf-8'})
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = 'cybershield-learning-report.html'
  link.click()
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}
function getPasswordFeedback(password: string) {
  if (!password) return { score: 0, label: 'Not evaluated', hints: ['Try a fictional example passphrase — never enter a real password.'] }
  let score = 0
  if (password.length >= 12) score++
  if (password.length >= 16) score++
  if (/[a-z]/.test(password) && /[A-Z]/.test(password)) score++
  if (/\d/.test(password) || /[^a-zA-Z]/.test(password)) score++
  if (/password|123456|qwerty|admin|letmein/i.test(password)) score = Math.min(score, 1)
  const hints = [password.length < 16 ? 'Longer passphrases are generally easier to remember and harder to guess.' : 'Good length for a fictional example.', 'Use a unique password for each account and enable multi-factor authentication.', 'This simple demonstration is not a real-world password security audit.']
  return { score, label: ['Very weak', 'Weak', 'Developing', 'Good example', 'Strong example'][score], hints }
}
