  function finishQuiz() { if (!quizComplete || quizSubmitted) return; setQuizSubmitted(true); setProgress(p => ({ ...p, quizBest: quizDifficulty === 'Beginner' && quizCategory === 'All topics' ? Math.max(p.quizBest || 0, quizScore) : p.quizBest, quizHistory: [...(p.quizHistory || []), {category: quizCategory, difficulty: quizDifficulty, score: quizScore, total: activeQuizQuestions.length, completedAt: new Date().toISOString(),kind:'attempt' as const}, ...((quizCategory === 'All topics') ? activeQuizQuestions.map((q,i) => ({category:q.category,difficulty:quizDifficulty,score:Number(quizAnswers[i] === q.correct),total:1,completedAt:new Date().toISOString(),kind:'topic' as const})) : [])].slice(-100) })) }
