      const parsed: unknown = JSON.parse(await file.text())
      const candidate = parsed && typeof parsed === 'object'
        ? ('progressBackup' in parsed ? (parsed as {progressBackup: unknown}).progressBackup : parsed)
        : null
      const restored = normalizeProgress(candidate)
